 "Im offiziellen Format von Gymi, BMS, LAP/QV, Matura und Basisprüfung – mit Schweizer Note. Oder lade eine alte Prüfung (PDF/Foto) hoch: Brainy baut eine neue im gleichen Stil.": "Official format of Gymnasium, BMS, LAP/QV, Matura and basic exam – with Swiss grade. Or upload an old exam (PDF/photo): Brainy creates a new one in the same style.",
