 "Mathematik (# min, ohne Taschenrechner): Grundoperationen und Kopfrechnen, Brüche/Dezimalzahlen, Masseinheiten umrechnen, Proportionalität und Dreisatz, Geometrie (Flächen, Umfang, Winkel, Körper, Konstruktion beschreiben), Knobel- und Textaufgaben aus dem Alltag. Lösungsweg gibt Teilpunkte. Viele mehrteilige Aufgaben mit steigender Schwierigkeit.": "Math (# min, no calculator): basic ops, mental math, fractions/decimals, unit conversion, proportionality & rule of three, geometry (areas, perimeter, angles, solids, describe constructions), everyday puzzles & word problems. Solution path gives partial points. Many multi‑part tasks with increasing difficulty.",
 "Mathematik Matura: Analysis (Ableitung, Kurvendiskussion, Integral, Extremalprobleme), Vektorgeometrie, Wahrscheinlichkeit/Kombinatorik, Folgen. Mehrteilige Aufgaben, vollständiger Lösungsweg.": "Math Matura: analysis (derivative, curve discussion, integral, extremal problems), vector geometry, probability/combinatorics, sequences. Multi‑part tasks, full solution required.",
