 "Anfrage abgelehnt": "Request denied",
 "Aufnahmeprüfung Berufsmaturitätsschule. Stoff bis und mit 1. Semester 3. Sek. Bestanden mit Schnitt ≥ 4.0, Mathe zählt oft doppelt.": "Admission test for Berufsmaturitätsschule. Material up to and including 1st semester 3rd secondary. Passed with average ≥ 4.0, maths often counts double.",
 "BMS Zürich: Aufnahmeprüfung & Musterprüfungen": "BMS Zürich: Admission test & sample exams",
