 "Der Plan und seine Sessions im Kalender werden entfernt. Deine bisherigen Lernsessions bleiben.": "The plan and its sessions are removed from the calendar. Your past study sessions stay.",
 "Deutsch (Duden erlaubt): Textverständnis eines Sachtexts, Grammatik und Sprachbetrachtung (Satzglieder, Konjunktiv, indirekte Rede, Kommaregeln) und ein Aufsatz/argumentativer Text.": "German (Duden allowed): reading comprehension of a factual text, grammar and language analysis (sentence parts, subjunctive, indirect speech, commas) and an essay/argumentative text.",
 "Deutsch BMP: Erörterung/Interpretation zu einem literarischen oder pragmatischen Text, Textanalyse, Sprachreflexion.": "German BMP: discussion/interpretation of a literary or pragmatic text, text analysis, language reflection.",
 "Deutsch Matura: Aufsatz (Erörterung, Interpretation eines Gedichts/Prosatexts, Essay) – Aufgaben mit Textbezug und Begründung.": "German Matura: essay (discussion, interpretation of a poem/prose, essay) – tasks with text reference and justification.",
 "Deutsch · Prüfung Fr, #. Oktober · noch # Tage": "German · exam Fri, # Oct · # days left",
 "Deutsch: Textverständnis zu einem Sachtext oder einer Erzählung (Fragen zum Inhalt, zur Absicht, zu Wortbedeutungen), Sprachbetrachtung (Wortarten, Satzglieder, Zeitformen, Rechtschreibung, Zeichensetzung) und ein kurzer Aufsatz/Schreibauftrag.": "German: reading comprehension of a factual or narrative text (questions on content, purpose, word meanings), language analysis (word classes, sentence parts, tenses, spelling, punctuation) and a short essay/writing task.",
