 "Coenzym": "Coenzyme",
 "Dabei wird": "Here,",
 "Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert.": "Energy is released, and part of it is stored in ATP.",
 "Dabei wird ein Molekül Glucose mit sechs Kohlenstoffatomen in zwei Moleküle Pyruvat mit je drei Kohlenstoffatomen gespalten. Der übrig bleibende Rest mit zwei Kohlenstoffatomen verbindet sich mit dem Coenzym A zum Acetyl-CoA.": "One glucose molecule (6 C) splits into two pyruvate molecules (3 C each). The remaining 2‑C fragment joins Coenzyme A to form Acetyl‑CoA.",
 "Danke dir! Jetzt bist du dran mit den Fragen.": "Thanks! Now it’s your turn with the questions.",
 "Danke für deine Erklärung.": "Thanks for your explanation.",
 "Das": "The",
 "Das Bild konnte nicht geladen werden.": "Image couldn’t be loaded.",
 "Das Material dieses Kurses fehlt auf diesem Gerät – bitte neu hochladen.": "The material for this course isn’t on this device – please upload it again.",
 "Das Pyruvat gelangt nun aus dem Zellplasma in die ____, die man oft als Kraftwerke der Zelle bezeichnet. Der übrig bleibende Rest mit zwei ____ verbindet sich mit dem Coenzym A zum Acetyl-CoA.": "Pyruvate now moves from the cytoplasm into the ____, often called the cell’s power plants. The leftover piece with two ____ joins Coenzyme A to form Acetyl‑CoA.",
 "Das Wichtigste": "The main thing",
 "Das ____ ist die Eintrittsstelle für den nächsten Abschnitt. Sauerstoff wird in diesem Abschnitt noch nicht verbraucht, doch der Zyklus steht still, wenn die ____ keinen Sauerstoff erhält.": "The ____ is the entry point for the next stage. Oxygen isn’t used here yet, but the cycle stops if the ____ doesn’t get oxygen.",
 "Das ____ und das ____.": "The ____ and the ____.",
 "Das dauert einen Moment. Du kannst die App offen lassen.": "That’ll take a moment. You can keep the app open.",
 "Das erste Wort steht dafür, dass dem Pyruvat Wasserstoff entzogen wird, das zweite dafür, dass eine Carboxylgruppe als Kohlenstoffdioxid abgespalten wird. Dabei werden zwei Moleküle Kohlenstoffdioxid abgespalten, und am Ende des Kreislaufs steht wieder Oxalacetat bereit, sodass der Zyklus von vorn beginnen kann.": "The first word means hydrogen is removed from pyruvate, the second means a carboxyl group is released as CO₂. Two CO₂ molecules are split off, and oxaloacetate is ready again so the cycle can start over.",
 "Das grosse Ziel wartet": "The big goal awaits",
 "Das hat nicht geklappt": "That didn’t work",
 "Das sitzt noch nicht": "That’s not set yet",
 "Datei entfernen": "Remove file",
