 "Deine bisherigen Antworten gehen verloren und der Versuch wird nicht gezählt.": "Your previous answers are lost and the attempt won’t count.",
 "Demo – ohne KI": "Demo – no AI",
 "Demo – ohne KI.": "Demo – no AI.",
 "Demo – ohne KI. Die Prüfung ist ein Beispiel; Kurzantworten und Aufsätze können nicht richtig korrigiert werden.": "Demo – no AI. The exam is an example; short answers and essays can’t be graded properly.",
 "Demo-Bewertung ohne KI (nur Länge und Schlüsselwörter): # Wörter. Eine inhaltliche Beurteilung gibt es nur mit der KI-Verbindung.": "Demo rating without AI (only length & keywords): # words. Content feedback is only available with AI.",
 "Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man Zellatmung.": "The stepwise breakdown of glucose using oxygen is called cellular respiration.",
