 "Der Citratzyklus in der Matrix": "The citric acid cycle in the matrix",
 "Der Citratzyklus in der Matrix: # Prozent": "Citric acid cycle in the matrix: # %",
 "Der Citratzyklus läuft ebenfalls in der Matrix der ____ ab. Weil aus einer Glucose zwei ____ entstehen, läuft der Zyklus pro Glucose zweimal.": "The citric acid cycle also runs in the ____ matrix. Because one glucose yields two ____, the cycle runs twice per glucose.",
 "Der Kurs und dein Fortschritt gehen verloren. Deine Originaldateien auf dem Gerät werden auch entfernt.": "The course and your progress will be lost. Your original files on the device will also be removed.",
 "Der Text ist noch zu kurz. Füge mehr Notizen ein oder lade eine Datei hoch.": "The text is still too short. Add more notes or upload a file.",
 "Der eingefügte Text ist zu lang (höchstens ca. 150 Seiten). Lade ihn als Datei hoch oder kürze ihn.": "The inserted text is too long (max ~150 pages). Upload it as a file or shorten it.",
 "Der wichtigste Brennstoff vieler Zellen ist die Glucose, also der Traubenzucker. Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man Zellatmung. Sie liefert den grössten Teil des ATP in tierischen und pflanzlichen Zellen. Man kann die Zellatmung in einer einzigen Gleichung zusammenfassen.": "Glucose, or grape sugar, is the main fuel for many cells. The stepwise breakdown of glucose with oxygen is called cellular respiration. It provides most of the ATP in animal and plant cells. You can sum up cellular respiration in one equation.",
 "Deshalb muss sie ATP laufend neu herstellen, indem sie energiereiche": "That’s why it constantly has to make new ATP by using high‑energy",
