 "Die Atmungskette an der inneren Membran": "The respiratory chain on the inner membrane",
 "Die Atmungskette an der inneren Membran: # Prozent": "Respiratory chain on the inner membrane: # %",
 "Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "The respiratory chain consists of several protein complexes that pass electrons along like steps.",
 "Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden. Am Ende der Kette nimmt Sauerstoff die Elektronen und Protonen auf und bildet damit Wasser. Wenn kein Sauerstoff vorhanden ist, kann die Zelle die Atmungskette nicht betreiben.": "The respiratory chain consists of several protein complexes that pass electrons like steps. At the end, oxygen grabs the electrons and protons to form water. Without oxygen, the cell can’t run the chain.",
