 "Die Mitochondrien besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "Mitochondria consist of several protein complexes that pass electrons like steps.",
 "Die Muskelzellen besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "Muscle cells consist of several protein complexes that pass electrons like steps.",
 "Die Protonen fliessen durch das Enzym ____ zurück in die Matrix. Fehlt der ____, staut sich die Kette zurück, und die Zelle kann kaum noch ATP auf diesem Weg herstellen.": "Protons flow back into the matrix via enzyme ____. If the ____ is missing, the chain backs up and the cell can hardly make ATP this way.",
