 "Eigener Text": "Custom text",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Decarboxylierung und sechs Molekülen Wasser.": "One glucose molecule reacts with six oxygen molecules into six decarboxylation molecules and six water molecules.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Intermembranraum und sechs Molekülen Wasser.": "One glucose molecule reacts with six oxygen molecules into six inter‑membrane‑space molecules and six water molecules.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Kohlenstoffdioxid und sechs Molekülen Wasser.": "One glucose molecule reacts with six oxygen molecules into six carbon‑dioxide molecules and six water molecules.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Kohlenstoffdioxid und sechs Molekülen Wasser. Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert. Der Rest geht als Wärme verloren, was erklärt, warum unser Körper warm bleibt. In Wirklichkeit läuft die Zellatmung nicht in einem Schritt ab.": "One glucose molecule reacts with six oxygen molecules into six CO₂ and six water molecules. Energy is released, part stored in ATP, the rest lost as heat – that’s why we stay warm. In reality cellular respiration isn’t a single step.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Stoffwechselweg und sechs Molekülen Wasser.": "One glucose molecule reacts with six oxygen molecules into six metabolic‑pathway molecules and six water molecules.",
