 "In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und Kohlenstoffdioxid.": "In our muscle cells this creates lactic acid, in yeast cells ethanol and carbon dioxide.",
 "Jede lebende Zelle muss ständig arbeiten.": "Every living cell must constantly work.",
 "Jede lebende Zelle muss ständig arbeiten. Sie baut Eiweisse auf, transportiert Stoffe durch ihre Membran, teilt sich und hält ihre Struktur aufrecht. Für alle diese Vorgänge benötigt sie Energie in einer Form, die sofort verfügbar ist. Diese Form ist das Molekül ATP, die Abkürzung für Adenosintriphosphat.": "Every living cell must constantly work. It builds proteins, transports substances across its membrane, divides and maintains its structure. All these processes need energy in an instantly available form – the molecule ATP (Adenosine Triphosphate).",
