 "Keine Antwort. Richtig wäre: D) Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "No answer. Correct would be: D) The respiratory chain is made of several protein complexes that pass electrons like stairs.",
