 "Richtig wäre: #: ATP-Synthase · #: Sauerstoff": "Correct would be: #: ATP synthase · #: Oxygen",
 "Richtig wäre: #: Acetyl-CoA · #: Atmungskette": "Correct would be: #: Acetyl‑CoA · #: Respiratory chain",
 "Richtig wäre: #: Adenosintriphosphat · #: Zellatmung": "Correct would be: #: Adenosine triphosphate · #: Cellular respiration",
