 "Richtig wäre: #: Kohlenstoffatomen · #: Kohlenstoffdioxid": "Correct would be: #: Carbon atoms · #: Carbon dioxide",
 "Richtig wäre: #: Mitochondrien · #: Acetyl-CoA": "Correct would be: #: Mitochondria · #: Acetyl‑CoA",
 "Richtig wäre: #: Mitochondrien · #: Kohlenstoffatomen": "Correct would be: #: Mitochondria · #: Carbon atoms",
 "Richtig wäre: #: Protonengefälle · #: ATP-Synthase": "Correct would be: #: Proton gradient · #: ATP synthase",
 "Richtig wäre: #: Wasserstoffatome · #: Eintrittsstelle": "Correct would be: #: Hydrogen atoms · #: Entry point",
 "Richtig wäre: A) a": "Correct would be: A) a",
 "Richtig wäre: C) c": "Correct would be: C) c",
 "Richtig wäre: eins → A · zwei → B": "Correct would be: one → A · two → B",
 "Richtig wäre: zwei → B": "Correct would be: two → B",
 "Richtig wären: A) a · C) c": "Correct would be: A) a · C) c",
 "Richtig wären: B) Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus. · D) Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "Correct would be: B) The carbon dioxide we exhale comes from oxidative decarboxylation and the citric acid cycle. · D) The respiratory chain consists of several protein complexes that pass electrons like stairs.",
 "Richtig – so steht es im Text.": "Correct – as the text says.",
 "Richtig: «": "Correct: «",
 "Richtig: «Energie» – so steht es im Text.": "Correct: «Energy» – as the text says.",
 "Richtig: «Zellatmung» – so steht es im Text.": "Correct: «Cellular respiration» – as the text says.",
 "Richtige Reihenfolge": "Correct order",
 "Richtige Reihenfolge: #. Diese Membran ist stark gefaltet, die Falten heissen Cristae. · #. Die frei werdende Energie wird genutzt, um Protonen aus der Matrix in den Intermembranraum zu pumpen. · #. Sauerstoff ist also der letzte Elektronenakzeptor. · #. Wenn kein Sauerstoff vorhanden ist, kann die Zelle die Atmungskette nicht betreiben.": "Correct order: #. This membrane is heavily folded, the folds are called Cristae. · #. The released energy is used to pump protons from the matrix into the inter‑membrane space. · #. Oxygen is the final electron acceptor. · #. Without oxygen the cell can’t run the respiratory chain.",
 "Richtige Reihenfolge: #. Dieser Schritt heisst oxidative Decarboxylierung. · #. Zuerst verbindet sich das Acetyl-CoA mit dem Molekül Oxalacetat zu Citrat, das Citrat hat sechs Kohlenstoffatome. · #. Weil aus einer Glucose zwei Acetyl-CoA entstehen, läuft der Zyklus pro Glucose zweimal. · #. Die Atmungskette sitzt in der inneren Membran der Mitochondrien.": "Correct order: #. This step is called oxidative decarboxylation. · #. First acetyl‑CoA joins oxaloacetate to form citrate, which has six carbon atoms. · #. Because one glucose yields two acetyl‑CoA, the cycle runs twice per glucose. · #. The respiratory chain sits in the inner mitochondrial membrane.",
 "Richtige Reihenfolge: #. Jede lebende Zelle muss ständig arbeiten. · #. ATP wirkt wie eine kleine, aufladbare Batterie der Zelle. · #. Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man Zellatmung. · #. Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert.": "Correct order: #. Every living cell has to keep working. · #. ATP is like a tiny rechargeable battery for the cell. · #. The step‑by‑step breakdown of glucose with oxygen is called cellular respiration. · #. Energy is released and part of it gets stored in ATP.",
 "Richtige Reihenfolge: #. So wird die Energie in kleinen Portionen frei und kann gezielt in ATP umgewandelt werden. · #. Zuerst muss die Zelle selbst zwei ATP einsetzen, um die Glucose zu aktivieren. · #. Die Glykolyse braucht keinen Sauerstoff. · #. Der übrig bleibende Rest mit zwei Kohlenstoffatomen verbindet sich mit dem Coenzym A zum Acetyl-CoA.": "Correct order: #. Energy is released in small bursts and can be turned into ATP. · #. First the cell spends two ATP to activate glucose. · #. Glycolysis doesn’t need oxygen. · #. The leftover two‑carbon piece joins CoA to become acetyl‑CoA.",
 "Richtige Reihenfolge: #. erst · #. dann · #. danach · #. zuletzt": "Correct order: #. first · #. then · #. after that · #. finally",
