 "Starte mit einem Skript, Fotos deiner Notizen oder einem eingefügten Text.": "Start with a script, photos of your notes or an inserted text.",
 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Decarboxylierung, der Citratzyklus und die Atmungskette.": "Instead, the cell breaks sugar into four stages: glycolysis, oxidative decarboxylation, the citric acid cycle and the respiratory chain.",
