 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Kohlenstoffdioxid, der Citratzyklus und die Atmungskette.": "Instead, the cell breaks sugar into four stages: glycolysis, oxidative carbon dioxide, the citric acid cycle and the respiratory chain.",
 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Stoffwechselweg, der Citratzyklus und die Atmungskette.": "Instead, the cell breaks sugar into four stages: glycolysis, oxidative metabolic pathway, the citric acid cycle and the respiratory chain.",
