 "Wörter in die Lücken setzen": "Insert words into gaps",
 "Würde die Glucose auf einmal verbrennen, entstünde ein Wärmeblitz, den die Zelle nicht nutzen könnte.": "If glucose burned all at once, a heat flash would appear that the cell couldn’t use.",
 "Würde die Glucose auf einmal verbrennen, entstünde ein Wärmeblitz, den die Zelle nicht nutzen könnte. Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Decarboxylierung, der Citratzyklus und die Atmungskette. So wird die Energie in kleinen Portionen frei und kann gezielt in ATP umgewandelt werden.": "If glucose burned all at once, a heat flash would appear that the cell couldn’t use. Instead the cell splits the sugar into four steps: glycolysis, oxidative decarboxylation, the citric acid cycle and the electron transport chain. Energy is released in small bites and can be turned into ATP.",
