 "«Am Ende der Kette nimmt Sauerstoff die Elektronen und Protonen auf und bildet damit Wasser.» ist richtig; «In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und Stoffwechselweg.» ist falsch; «Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird Energie frei, die die Zelle für ihre Arbeit nutzen kann.» ist richtig.": "\"At the end of the chain oxygen takes up electrons and protons forming water.\" is correct; \"In our muscle cells this makes lactic acid, in yeast cells ethanol and a metabolic pathway.\" is wrong; \"When a phosphate group splits off ATP, ADP forms and energy is released for the cell to use.\" is correct.",
