 "ATP wirkt wie eine kleine, aufladbare Batterie der Zelle.": "ATP works like a tiny rechargeable battery of the cell.",
 "ATP wirkt wie eine kleine, aufladbare Batterie der Zelle. Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird Energie frei, die die Zelle für ihre Arbeit nutzen kann. Die Zelle kann ATP nicht in grossen Mengen lagern. Deshalb muss sie ATP laufend neu herstellen, indem sie energiereiche Nährstoffe abbaut.": "ATP works like a tiny rechargeable battery of the cell. When a phosphate group is split off ATP, ADP is formed, releasing energy that the cell can use for its work. The cell cannot store ATP in large amounts. Therefore it must continuously produce new ATP by breaking down energy‑rich nutrients.",
