 "Das Carboxylgruppe, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "The carboxyl group we exhale comes from oxidative decarboxylation and the citric acid cycle.",
 "Das Intermembranraum, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "The intermembrane space we exhale comes from oxidative decarboxylation and the citric acid cycle.",
