 "De": "De",
 "Der Basistext war zu kurz (basis). Bitte nochmals versuchen.": "The base text was too short. Please try again.",
 "Der Citratzyklus in der Matrix · # % richtig": "Citric acid cycle in matrix · # % correct",
 "Der Citratzyklus in der Matrix · ca. # Min. · das dauert nur einen Moment.": "Citric acid cycle in matrix · approx # min · it only takes a moment.",
 "Der Citratzyklus in der Matrix, Läuft. Etappe öffnen": "Citric acid cycle in matrix, running. Open stage",
 "Der Citratzyklus in der Matrix, Offen. Etappe öffnen": "Citric acid cycle in matrix, open. Open stage",
 "Der Druck gibt an, wie stark eine Kraft auf eine": "Pressure indicates how strong a force is on a",
 "Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck. Der Druck ist der Quotient aus Kraft und Fläche.": "Pressure shows how strong a force is on a specific area. Same force creates high pressure on a small area and low pressure on a large area. Pressure = force ÷ area.",
 "Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck. Deshalb sinkt man mit Schuhen im Schnee tiefer ein als mit breiten Skiern. Der Druck ist der Quotient aus Kraft und Fläche.": "Pressure shows how strong a force is on a specific area. Same force gives high pressure on a small area and low pressure on a large area. That’s why you sink deeper in snow with shoes than with wide skis. Pressure = force ÷ area.",
 "Der Druck ist der": "Pressure is the",
 "Der Druck ist der Quotient aus Kraft und Alltag.": "Pressure is the quotient of force and everyday life.",
 "Der Druck ist der Quotient aus Kraft und Arbeit.": "Pressure is the quotient of force and work.",
 "Der Druck ist der Quotient aus Kraft und Fläche.": "Pressure is the quotient of force and area.",
