 "Eine Kraft kann einen Körper beschleunigen, abbremsen oder verformen. Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu ändern. Die Einheit der Kraft ist das Newton. Ein Newton beschleunigt eine Masse von einem Kilogramm in jeder Sekunde um einen Meter pro Sekunde.": "A force can accelerate, brake or deform a body. The larger the mass, the more force you need to change its speed. The unit is the newton. One newton accelerates a one‑kilogram mass by one metre per second each second.",
