 "In der Physik wird Arbeit verrichtet, wenn eine Kraft einen Körper über eine Strecke bewegt.": "In der Physik wird Arbeit geleistet, wenn du eine Kraft einen Körper über eine Strecke schiebst.",
 "In der Physik wird Arbeit verrichtet, wenn eine Kraft einen Körper über eine Strecke bewegt. Wer eine Kiste nur festhält, ohne sie zu bewegen, verrichtet im physikalischen Sinn keine Arbeit. Die Arbeit ist umso grösser, je grösser die Kraft und je länger der Weg ist. Gemessen wird sie in Joule.": "In der Physik wird Arbeit geleistet, wenn du eine Kraft einen Körper über eine Strecke schiebst. Wer eine Kiste nur hält, ohne sie zu bewegen, leistet physikalisch keine Arbeit. Arbeit steigt mit Kraft und Weglänge. Gemessen wird sie in Joule.",
