 "Setze zuerst in alle Lücken ein Wort ein.": "First fill every gap with a word.",
 "Siehe Basistext: Abschnitt # «Der Citratzyklus in der Matrix» – «Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus»": "See source: section # “The citric acid cycle in the matrix” – “The carbon dioxide we exhale therefore comes from oxidative decarboxylation and from”",
 "Siehe Basistext: Abschnitt # «Der Citratzyklus in der Matrix» – «Sauerstoff wird in diesem Abschnitt noch nicht verbraucht, doch der Zyklus steht still, wenn die»": "See source: section # “The citric acid cycle in the matrix” – “Oxygen isn’t used yet in this section, but the cycle stops when the”",
 "Siehe Basistext: Abschnitt # «Dichte» – «Die Dichte beschreibt, wie viel Masse in einem bestimmten Volumen steckt.»": "See source: section # “Density” – “Density describes how much mass is in a given volume.”",
 "Siehe Basistext: Abschnitt # «Die Atmungskette an der inneren Membran» – «Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen»": "See source: section # “The respiratory chain on the inner membrane” – “The respiratory chain consists of several protein complexes, through which electrons move like stairs”",
 "Siehe Basistext: Abschnitt # «Druck» – «$p = \\frac{F}{A}$ (p: Druck, F: Kraft, A: Fläche)»": "See source: section # “Pressure” – “$p = \\frac{F}{A}$ (p: pressure, F: force, A: area)”",
 "Siehe Basistext: Abschnitt # «Druck» – «Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt.»": "See source: section # “Pressure” – “Pressure indicates how strong a force acts on a certain area.”",
 "Siehe Basistext: Abschnitt # «Druck» – «Der Druck ist der Quotient aus Kraft und Fläche.»": "See source: section # “Pressure” – “Pressure is the quotient of force and area.”",
 "Siehe Basistext: Abschnitt # «Druck» – «Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche»": "See source: section # “Pressure” – “The same force creates high pressure on a small area and low pressure on a large area”",
 "Siehe Basistext: Abschnitt # «Energie und Glucose im Überblick» – «Die Energie verbindet die Protein und hängt eng mit der Stoffwechsel und dem Energie zusammen, weil»": "See source: section # “Energy and glucose at a glance” – “Energy links proteins and is closely tied to metabolism and energy because”",
 "Siehe Basistext: Abschnitt # «Energie und Glucose im Überblick» – «Die Mitochondrium verbindet die Chromosom und hängt eng mit der Zelle und dem Chromosom zusammen,»": "See source: section # “Energy and glucose at a glance” – “The mitochondrion links chromosomes and is closely tied to the cell and chromosomes,”",
 "Siehe Basistext: Abschnitt # «Geschwindigkeit» – «$v = \\frac{s}{t}$ (v: Geschwindigkeit, s: Strecke, t: Zeit)»": "See source: section # “Speed” – “$v = \\frac{s}{t}$ (v: speed, s: distance, t: time)”",
 "Siehe Basistext: Abschnitt # «Geschwindigkeit» – «Die Geschwindigkeit sagt, wie schnell sich ein Körper bewegt.»": "See source: section # “Speed” – “Speed tells how fast an object moves.”",
 "Siehe Basistext: Abschnitt # «Kohlenstoffdioxid» – «Bei Aminosäuren wird zuerst die Aminogruppe abgespalten, der Rest tritt an verschiedenen Stellen in»": "See source: section # “Carbon dioxide” – “In amino acids the amino group is removed first, the rest appears in various places in”",
 "Siehe Basistext: Abschnitt # «Kohlenstoffdioxid» – «In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und»": "See source: section # “Carbon dioxide” – “In our muscle cells this creates lactic acid, in yeast cells ethanol and”",
 "Siehe Basistext: Abschnitt # «Kraft» – «Ein Newton beschleunigt eine Masse von einem Kilogramm in jeder Sekunde um einen Meter pro Sekunde.»": "See source: section # “Force” – “One newton accelerates a mass of one kilogram by one meter per second each second.”",
 "Siehe Basistext: Abschnitt # «Kraft» – «Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu»": "See source: section # “Force” – “The larger a body’s mass, the more force you need to change its speed.”",
 "Siehe Basistext: Abschnitt # «Membran und Gen im Überblick» – «Die Ribosom liefert die Allel und hängt eng mit der Stoffwechsel und dem Vererbung zusammen, weil»": "See source: section # “Membrane and gene at a glance” – “The ribosome provides the allele and is closely linked to metabolism and inheritance because”",
 "Siehe Basistext: Abschnitt # «Membran und Gen im Überblick» – «Die Stoffwechsel baut ab die Muskel und hängt eng mit der Chromosom und dem Ribosom zusammen, weil»": "See source: section # “Membrane and gene at a glance” – “Metabolism breaks down muscle and is closely linked to chromosomes and the ribosome because”",
